CREATE OR ALTER PROCEDURE [dbo].[uspPricePolicy_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @CustomerId UNIQUEIDENTIFIER = NULL
	, @ContractId UNIQUEIDENTIFIER = NULL
	, @MealType NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @Code NVARCHAR(MAX) = NULL
	, @Name NVARCHAR(MAX) = NULL
	, @UnitPrice DECIMAL(18,2) = NULL
	, @CurrencyCode NVARCHAR(MAX) = NULL
	, @EffectiveFrom DATETIME = NULL
	, @EffectiveTo DATETIME = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[CustomerId]
			, j1.[DisplayName] AS [CustomerName]
			, t.[ContractId]
			, j2.[Name] AS [ContractName]
			, t.[MealType]
			, t.[UnitPrice]
			, t.[EffectiveFrom]
			, t.[EffectiveTo]
			, t.[Status]
			, t.[Code]
			, t.[Name]
			, t.[CurrencyCode]
			, t.[CreatedDate]
		FROM [dbo].[PricePolicie] AS t
		LEFT JOIN [dbo].[Customer] AS j1 ON j1.[Id] = t.[CustomerId]
		LEFT JOIN [dbo].[Contract] AS j2 ON j2.[Id] = t.[ContractId]
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[Name] LIKE CONCAT('%', @SearchText, '%') OR t.[CurrencyCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (@CustomerId IS NULL OR t.[CustomerId] = @CustomerId)
			AND (@ContractId IS NULL OR t.[ContractId] = @ContractId)
			AND (ISNULL(@MealType, '') = '' OR t.[MealType] = @MealType)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND (ISNULL(@Code, '') = '' OR t.[Code] LIKE CONCAT('%', @Code, '%'))
			AND (ISNULL(@Name, '') = '' OR t.[Name] LIKE CONCAT('%', @Name, '%'))
			AND (@UnitPrice IS NULL OR t.[UnitPrice] = @UnitPrice)
			AND (ISNULL(@CurrencyCode, '') = '' OR t.[CurrencyCode] LIKE CONCAT('%', @CurrencyCode, '%'))
			AND (@EffectiveFrom IS NULL OR t.[EffectiveFrom] = @EffectiveFrom)
			AND (@EffectiveTo IS NULL OR t.[EffectiveTo] = @EffectiveTo)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerId' THEN r.[CustomerId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerId' THEN r.[CustomerId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'customerName' THEN r.[CustomerName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'customerName' THEN r.[CustomerName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractId' THEN r.[ContractId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractId' THEN r.[ContractId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'contractName' THEN r.[ContractName] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'contractName' THEN r.[ContractName] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'mealType' THEN r.[MealType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'mealType' THEN r.[MealType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'unitPrice' THEN r.[UnitPrice] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'unitPrice' THEN r.[UnitPrice] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveFrom' THEN r.[EffectiveFrom] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'effectiveTo' THEN r.[EffectiveTo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'name' THEN r.[Name] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'name' THEN r.[Name] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'currencyCode' THEN r.[CurrencyCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'currencyCode' THEN r.[CurrencyCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
